server {
    listen 443 ssl http2;
    server_name {domain};
    ssl_certificate /etc/ssl/{domain}.pem;
    location / {
        proxy_pass http://{backend};
    }
    location /static/ {
        root /var/www;
        expires 30d;
    }
}

